// Some portions generated by Claude
import type { Graph, GraphNode, PointerPosition } from "./graph-types.ts";
import {graphNodeSize} from './graph-geometry.ts';

/** Metadata can resize cards without changing the topology revision. */
export function layoutDimensionsChanged(before: readonly GraphNode[], after: readonly GraphNode[]) {
  if (before.length !== after.length) return true;
  for (let i = 0; i < after.length; i++) {
    const a = before[i], b = after[i];
    if (a.id !== b.id) return true;
    if (a.label === b.label && a.kind === b.kind) continue;
    const x = graphNodeSize(a), y = graphNodeSize(b);
    if (x.width !== y.width || x.height !== y.height) return true;
  }
  return false;
}

/** Coordinates change every frame; semantic analyses depend only on metadata. */
export function createNodeMetadataSelector() {
  let previous: GraphNode[] = [];
  return (nodes: GraphNode[]) => {
    if (previous.length === nodes.length && nodes.every((node, index) => {
      const old = previous[index];
      return node === old || (node.id === old.id && node.label === old.label &&
        node.kind === old.kind && node.types === old.types && node.datatype === old.datatype &&
        node.language === old.language && node.direction === old.direction && node.termValue === old.termValue &&
        node.pinned === old.pinned);
    })) return previous;
    previous = nodes;
    return nodes;
  };
}

/** Merge coordinates onto current metadata, including labels hydrated mid-layout. */
export function applyGraphPositions(graph: Graph, positions: ReadonlyMap<string, PointerPosition>): Graph {
  return {
    ...graph,
    nodes: graph.nodes.map(node => {
      const position = positions.get(node.id);
      return position ? { ...node, ...position } : node;
    }),
  };
}
